using namespace std;

int main() {
    int m, n, x, p, q, u, v;
    cin >> m >> n >> x >> p >> q >> u >> v;
    int start = (p - 1) * n + (q - 1), target = (u - 1) * n + (v - 1);
    if (start == target) {
        cout << 0 << '\n';
        return 0;
    }
    // All integer displacements (dr, dc) with dr^2 + dc^2 = x^2.
    set<pair<int, int>> moves;
    for (int dr = 0; dr <= x; dr++) {
        int rem = x * x - dr * dr, dc = (int)sqrt((double)rem);
        while (dc * dc > rem) dc--;
        while ((dc + 1) * (dc + 1) <= rem) dc++;
        if (dc * dc == rem)
            for (int a : {dr, -dr})
                for (int b : {dc, -dc}) moves.insert({a, b});
    }
    moves.erase({0, 0});
    // Unweighted BFS over cells: the first visit of the target gives the fewest jumps.
    vector<int> dist(m * n, -1), queue = {start};
    dist[start] = 0;
    for (size_t head = 0; head < queue.size(); head++) {
        int cur = queue[head], r = cur / n, c = cur % n, nd = dist[cur] + 1;
        for (auto [dr, dc] : moves) {
            int nr = r + dr, nc = c + dc;
            if (nr < 0 || nr >= m || nc < 0 || nc >= n) continue;
            int next = nr * n + nc;
            if (dist[next] >= 0) continue;
            if (next == target) {
                cout << nd << '\n';
                return 0;
            }
            dist[next] = nd;
            queue.push_back(next);
        }
    }
    cout << -1 << '\n';
}

import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        int m = nextInt(), n = nextInt(), x = nextInt(), p = nextInt(), q = nextInt(), u = nextInt(), v = nextInt();
        int start = (p - 1) * n + (q - 1), target = (u - 1) * n + (v - 1);
        if (start == target) {
            System.out.println(0);
            return;
        }
        // All integer displacements (dr, dc) with dr^2 + dc^2 = x^2.
        Set<Long> seenMove = new HashSet<>();
        List<int[]> moves = new ArrayList<>();
        for (int dr = 0; dr <= x; dr++) {
            int rem = x * x - dr * dr, dc = (int) Math.sqrt(rem);
            while (dc * dc > rem) dc--;
            while ((dc + 1) * (dc + 1) <= rem) dc++;
            if (dc * dc != rem) continue;
            for (int a : new int[] {dr, -dr})
                for (int b : new int[] {dc, -dc})
                    if ((a != 0 || b != 0) && seenMove.add(a * 4096L + b)) moves.add(new int[] {a, b});
        }
        // Unweighted BFS over cells: the first visit of the target gives the fewest jumps.
        int[] dist = new int[m * n], queue = new int[m * n];
        Arrays.fill(dist, -1);
        dist[start] = 0;
        int head = 0, tail = 0;
        queue[tail++] = start;
        while (head < tail) {
            int cur = queue[head++], r = cur / n, c = cur % n, nd = dist[cur] + 1;
            for (int[] mv : moves) {
                int nr = r + mv[0], nc = c + mv[1];
                if (nr < 0 || nr >= m || nc < 0 || nc >= n) continue;
                int next = nr * n + nc;
                if (dist[next] >= 0) continue;
                if (next == target) {
                    System.out.println(nd);
                    return;
                }
                dist[next] = nd;
                queue[tail++] = next;
            }
        }
        System.out.println(-1);
    }
}

package main

import (
	"fmt"
	"io"
	"math"
	"os"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	m, n, x := int(nextInt()), int(nextInt()), int(nextInt())
	p, q, u, v := int(nextInt()), int(nextInt()), int(nextInt()), int(nextInt())
	start, target := (p-1)*n+(q-1), (u-1)*n+(v-1)
	if start == target {
		fmt.Println(0)
		return
	}
	// All integer displacements (dr, dc) with dr^2 + dc^2 = x^2.
	seenMove := map[[2]int]bool{}
	var moves [][2]int
	for dr := 0; dr <= x; dr++ {
		rem := x*x - dr*dr
		dc := int(math.Sqrt(float64(rem)))
		for dc*dc > rem {
			dc--
		}
		for (dc+1)*(dc+1) <= rem {
			dc++
		}
		if dc*dc != rem {
			continue
		}
		for _, a := range []int{dr, -dr} {
			for _, b := range []int{dc, -dc} {
				mv := [2]int{a, b}
				if mv != [2]int{0, 0} && !seenMove[mv] {
					seenMove[mv] = true
					moves = append(moves, mv)
				}
			}
		}
	}
	// Unweighted BFS over cells: the first visit of the target gives the fewest jumps.
	dist := make([]int32, m*n)
	for i := range dist {
		dist[i] = -1
	}
	dist[start] = 0
	queue := []int32{int32(start)}
	for head := 0; head < len(queue); head++ {
		cur := int(queue[head])
		r, c, nd := cur/n, cur%n, dist[cur]+1
		for _, mv := range moves {
			nr, nc := r+mv[0], c+mv[1]
			if nr < 0 || nr >= m || nc < 0 || nc >= n {
				continue
			}
			next := nr*n + nc
			if dist[next] >= 0 {
				continue
			}
			if next == target {
				fmt.Println(nd)
				return
			}
			dist[next] = nd
			queue = append(queue, int32(next))
		}
	}
	fmt.Println(-1)
}
